/** Dev: proxied via vite.config; production static build has no proxy */
const anthropicMessagesUrl = import.meta.env.DEV ? "/api/anthropic/v1/messages" : null;
/* ═══════ AI ═══════ */
async function genQs(cats,country){
  const prompt=`Generate trivia quiz JSON. ${country.id==="general"?"Worldwide general knowledge":"EXCLUSIVELY about "+country.name}.
Categories: ${cats.map(c=>c.n).join(", ")}
For EACH category generate exactly 60 unique questions with 4 options and 1 correct answer.
${country.id!=="general"?`ALL questions must be specifically about ${country.name} — its history, culture, people, landmarks, food, sports, traditions, arts, media, science, geography, politics. Use REAL facts.`:"Use diverse topics — history, science, pop culture, geography, sports, arts, literature, technology. REAL facts only."}
Write in ${country.dialect}.
CRITICAL RULES:
- All 4 answer options MUST be very similar and plausible — close numbers, similar names, related concepts
- NO obviously wrong answers. Every option should make the player think hard
- Questions should be HARD difficulty
- Randomize correct answer index (0-3) evenly
RESPOND WITH ONLY VALID JSON (no markdown, no backticks):
{"categories":{"catId":[{"q":"question","o":["opt1","opt2","opt3","opt4"],"a":correctIndex}]}}
Category IDs: ${cats.map(c=>c.id).join(",")}`;
  try{
    if(!anthropicMessagesUrl)return null;
    const controller=new AbortController();
    const timeout=setTimeout(()=>controller.abort(),12000);
    const r=await fetch(anthropicMessagesUrl,{method:"POST",headers:{"Content-Type":"application/json"},signal:controller.signal,body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:8000,messages:[{role:"user",content:prompt}]})});
    clearTimeout(timeout);
    const d=await r.json();const txt=(d.content||[]).map(i=>i.text||"").join("");
    const clean=txt.replace(/```json|```/g,"").trim();
    const parsed=JSON.parse(clean);
    return parsed.categories||parsed;
  }catch{return null}
}

// Question cache system with bulk download
function loadCache(){try{const d=localStorage.getItem("qadha_qcache");return d?JSON.parse(d):{}}catch{return{}}}
function saveCache(c){try{localStorage.setItem("qadha_qcache",JSON.stringify(c))}catch{/* ignore */}}
function loadSeen(){try{const d=localStorage.getItem("qadha_seen");return d?new Set(JSON.parse(d)):new Set()}catch{return new Set()}}
function saveSeen(s){try{localStorage.setItem("qadha_seen",JSON.stringify([...s].slice(-2000)))}catch{/* ignore */}}
function qHash(q){return(q.q||"").substring(0,40)}
function getCacheCount(){const c=loadCache();let t=0;Object.values(c).forEach(v=>t+=v.length);return t}

// Generate questions for a batch of categories
async function genBatch(catIds,country){
  const cats=catIds.map(id=>CATS.find(c=>c.id===id)).filter(Boolean);
  if(!cats.length)return null;
  const prompt=`Generate trivia JSON. ${country.id==="general"?"Worldwide general knowledge":"EXCLUSIVELY about "+country.name}.
Categories: ${cats.map(c=>c.n).join(", ")}
Each category: 80 unique hard questions, 4 VERY SIMILAR options, 1 correct.
Write in ${country.dialect}. All options must be plausible and intentionally confusing. Randomize correct 0-3.
ONLY JSON: {"categories":{"catId":[{"q":"text","o":["a","b","c","d"],"a":num}]}}
IDs: ${catIds.join(",")}`;
  try{
    if(!anthropicMessagesUrl)return null;
    const ctrl=new AbortController();setTimeout(()=>ctrl.abort(),15000);
    const r=await fetch(anthropicMessagesUrl,{method:"POST",headers:{"Content-Type":"application/json"},signal:ctrl.signal,body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:8000,messages:[{role:"user",content:prompt}]})});
    const d=await r.json();const txt=(d.content||[]).map(i=>i.text||"").join("");
    const p=JSON.parse(txt.replace(/```json|```/g,"").trim());
    return p.categories||p;
  }catch{return null}
}

// Bulk download — generates questions for ALL categories in batches
async function bulkDownload(country,onProgress){
  const cache=loadCache();
  const cacheKey=country.id;
  const allIds=CATS.map(c=>c.id);
  const batchSize=3; // smaller batches for higher response quality
  const batches=[];
  for(let i=0;i<allIds.length;i+=batchSize){batches.push(allIds.slice(i,i+batchSize))}
  
  let done=0;
  for(const batch of batches){
    const result=await genBatch(batch,country);
    if(result){
      batch.forEach(catId=>{
        const key=`${cacheKey}_${catId}`;
        const existing=cache[key]||[];
        const newQs=result[catId]||[];
        // Merge and deduplicate
        const all={};
        existing.forEach(q=>{const h=qHash(q);if(!all[h])all[h]=q});
        newQs.forEach(q=>{const h=qHash(q);if(!all[h])all[h]=q});
        cache[key]=Object.values(all).slice(0,600); // max 600 per category
      });
    }
    done++;
    if(onProgress)onProgress(Math.round((done/batches.length)*100));
  }
  saveCache(cache);
  return getCacheCount();
}

function getQuestions(cats,cid,apiResult){
  const cache=loadCache();
  const seen=loadSeen();
  const bank=cid==="kw"?KW:GEN_AR;
  const result={};
  
  cats.forEach(c=>{
    let allQs=[];
    if(apiResult&&apiResult[c.id]&&Array.isArray(apiResult[c.id]))allQs=allQs.concat(apiResult[c.id]);
    const cacheKey=`${cid}_${c.id}`;
    if(cache[cacheKey])allQs=allQs.concat(cache[cacheKey]);
    if(bank[c.id])allQs=allQs.concat(bank[c.id]);
    
    const unique={};
    allQs.forEach(q=>{if(q&&q.q&&q.o){const h=qHash(q);if(!unique[h])unique[h]=q}});
    const allUnique=Object.values(unique);
    const unseen=allUnique.filter(q=>!seen.has(qHash(q)));
    const pick=unseen.length>=6?unseen:allUnique;
    const shuffled=shuf(pick).slice(0,40);
    result[c.id]=shuffled;
    shuffled.forEach(q=>seen.add(qHash(q)));
    
    // Update cache
    cache[cacheKey]=allUnique.slice(0,600);
  });
  
  saveSeen(seen);
  saveCache(cache);
  return result;
}
